import{_ as t,l as n,o as a,c as r,v as o,p as s,x as l,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"内存热插拔","description":"","frontmatter":{"title":"内存热插拔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-hotplug.md","filePath":"cs/memory-hotplug.md","lastUpdated":1789023840000}'),f={name:"cs/memory-hotplug.md"};function m(u,e,h,A,E,B){const i=n("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="内存热插拔" tabindex="-1">内存热插拔 <a class="header-anchor" href="#内存热插拔" aria-label="Permalink to &quot;内存热插拔&quot;">​</a></h1><div class="epigraph"><p>热插拔把一段 pfn 标成 online/offline：下线前必须迁移走可移页，留下的是不可移内核页则失败。</p><footer>—— 据 Linux memory hotplug 文档；ACPI 内存设备说明</footer></div><p><a href="/cs/page-migration-compaction">迁移</a> 是原语。<a href="/cs/userfaultfd">uffd</a> 改的是虚存内容来源。缺口是 <strong>物理容量变化</strong>：虚拟机 balloon 的亲戚在后课，这里先钉内核热插拔。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>probe</code> 新内存：加 zone/section，online 后 buddy 可用。offline：isolate 该范围，migrate，从 buddy 摘掉。缺口：内核代码/不可移 slab 钉在范围内则 -EBUSY；MOVABLE zone 专为可下线而设；与 <a href="/cs/numa-mempolicy">NUMA</a> 节点增减。本课不把每家固件通知写成 ACPI 手册。</p><p><span class="marginnote">稀疏内存模型用 section 粒度。CMA、kexec 与热插拔共享「可移性」概念。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>online：初始化 page 结构，交给 buddy。offline：<code>offline_pages</code> 循环迁移。对照 <a href="/cs/md-raid">md</a> 热备：一个加盘，一个加 RAM。对照 DAX：PMEM 命名空间 online 是同类路径。</p>',8)),(a(),s(c,null,{default:l(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22%E5%9B%BA%E4%BB%B6%E9%80%9A%E7%9F%A5%E6%96%B0%E5%86%85%E5%AD%98%22%5D%20--%3E%20ON%5B%22online%20%E8%BF%9B%20buddy%22%5D%0A%20%20OFF%5B%22%E8%AF%B7%E6%B1%82%20offline%22%5D%20--%3E%20MIG%5B%22%E8%BF%81%E5%87%BA%E5%8F%AF%E7%A7%BB%E9%A1%B5%22%5D%0A%20%20MIG%20--%3E%7C%22%E6%AE%8B%E7%95%99%E9%92%89%E9%A1%B5%22%7C%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20MIG%20--%3E%7C%22%E7%A9%BA%22%7C%20RM%5B%22%E4%BB%8E%20buddy%20%E7%A7%BB%E9%99%A4%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>热插拔让容量成为运行时变量，云与大型机依赖它。失败模式教会「内核数据放置」：不该把不可移对象放进可下线 zone。不要写成硬件采购。与 memcg：上限按页，容量减少会全局更紧。</p><p>和 inflight DMA：必须先停设备或 bounce。</p><p>实现上：section 粒度意味着不能下线任意一页。内核 .data 若落在可下线区，offline 永远失败，所以 ZONE_MOVABLE 存在。ACPI 通知与手动 probe 是两条上线路径。 读法上只引用<a href="/cs/userfaultfd">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>内存热插拔</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CXL 热插的全部。不保证 32 位系统可用。下一课内核自己的非连续虚映射：vmalloc。</p><p>版本字段会变，课序钉的是机制对象「内存热插拔」，不是某一主线内核的结构体名。 后课默认：pfn 范围可 online/offline，依赖迁移。内核 vmalloc 区如何拼页，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>热插拔 online/offline pfn；钉页会挡住线。</li><li>MOVABLE 提高可下线性。</li><li>vmalloc 是下一课。</li><li>出处：Linux memory hotplug；ACPI；Gorman。</li></ul>',11))])}const g=t(f,[["render",m]]);export{b as __pageData,g as default};
